INSERT INTO "AppSetting" ("key", "value", "updatedAt")
VALUES ('MCP_GUIDE', E'## Repartition magasin 2026-10-01\nLes 50 offres visent RARITY_LOOT_WEIGHTS via quotas entiers au plus fort reste. Au moins une LEGENDARY est reservee quand le catalogue et les plafonds le permettent. Selection aleatoire de sujets distincts eligibles, des raretes hautes vers les basses, avec plafonds globaux et reservations actives. Un quota impossible est redistribue vers les raretes disponibles; seule l absence de 50 sujets distincts vendables bloque la rotation. Aucun changement aux boosters ni aux combats.', CURRENT_TIMESTAMP)
